***
The GraphQl query for this endpoint is:
``` graphql
mutation insert($miniappId: String!, $sourceType: String!, $featuresHaptics: Boolean, $featuresCameraAndMic: Boolean, $clientPlatformType: String, $clientFarcasterId: Int, $user: users_obj_rel_insert_input!) {
  insert_sources_one(object: {miniapp_id: $miniappId, source_type: $sourceType, features_haptics: $featuresHaptics, features_camera_and_microphone_access: $featuresCameraAndMic, client_miniapp_platform_type: $clientPlatformType, client_farcaster_id: $clientFarcasterId, user: $user}) {
    recorded_at
    features_haptics
    features_camera_and_microphone_access
    client_miniapp_platform_type
    client_farcaster_id
    user_id
    user {
      farcaster_id
      username
      displayName
      pfpUrl
    }
  }
}
```

get.description:
***
The GraphQl query for this endpoint is:
``` graphql
query top_users($miniappId: String!, $limit: Int! = 10, $offset: Int! = 0) {
  users(where: {sources: {miniapp_id: {_eq: $miniappId}}}, order_by: {sources_aggregate: {count: desc}}, limit: $limit, offset: $offset) {
    farcaster_id
    username
    displayName
    pfpUrl
    sources_aggregate(where: {miniapp_id: {_eq: $miniappId}}) {
      aggregate {
        count
      }
    }
  }
}
```

***
The GraphQl query for this endpoint is:
``` graphql
query user($farcasterId: String!, $limit: Int! = 25, $offset: Int! = 0) {
  users(where: {farcaster_id: {_eq: $farcasterId}}, limit: 1) {
    farcaster_id
    username
    displayName
    pfpUrl
    sources(order_by: {recorded_at: desc}, limit: $limit, offset: $offset) {
      miniapp_id
      source_type
      recorded_at
      features_haptics
      features_camera_and_microphone_access
      client_miniapp_platform_type
      client_farcaster_id
    }
    sourcesAggregate: sources_aggregate {
      aggregate {
        count
      }
    }
  }
}
```
